use crate::{app::Desktop,ui::*,views::{backend::{Command,HostAction,IdentityAction,SettingsKind},forms::Editor}};
use gpui_kit::{component::{button::Button,Disableable},*};
use std::collections::BTreeMap;

impl Desktop {
 pub(crate) fn devices(&self,cx:&mut Context<Self>)->AnyElement{let mut page=self.page().child(self.button("invite","生成邀请",Command::Identity(IdentityAction::Invite),cx)).child(self.button("join-requests","读取加入请求",Command::Identity(IdentityAction::Requests),cx));for member in &self.snapshot.members{let mut row=self.row(member.name.clone(),format!("{} · {}",member.kind,if member.manage{"管理设备"}else{"普通成员"}));if self.snapshot.can_manage{row=row.child(self.open_editor(SharedString::from(format!("rename-{}",member.device_id)),"重命名",Editor::Member(member.device_id.clone()),BTreeMap::from([("name",member.name.clone())]),cx)).child(self.button(SharedString::from(format!("grant-{}",member.device_id)),if member.manage{"取消管理权限"}else{"授予管理权限"},Command::Identity(IdentityAction::Grant{device_id:member.device_id.clone(),manage:!member.manage}),cx)).child(self.ask(SharedString::from(format!("revoke-{}",member.device_id)),"撤销成员",Command::Identity(IdentityAction::Revoke(member.device_id.clone())),cx));}page=page.child(row);}for join in &self.snapshot.joins{let mut row=self.row(join.name.clone(),join.code.as_ref().map(|code|format!("核对短码：{code}")).unwrap_or_else(||"先发送核对请求，再在两台设备比较短码。".into()));if join.code.is_none(){row=row.child(self.button(SharedString::from(format!("join-confirm-{}",join.join_id)),"开始短码核对",Command::Identity(IdentityAction::ConfirmJoin(join.join_id.clone())),cx));}else{row=row.child(self.ask(SharedString::from(format!("join-grant-{}",join.join_id)),"短码一致，允许加入",Command::Identity(IdentityAction::GrantJoin{join_id:join.join_id.clone(),manage:false}),cx)).child(self.ask(SharedString::from(format!("join-manager-{}",join.join_id)),"短码一致，作为管理设备加入",Command::Identity(IdentityAction::GrantJoin{join_id:join.join_id.clone(),manage:true}),cx));}page=page.child(row.child(self.button(SharedString::from(format!("join-reject-{}",join.join_id)),"拒绝加入",Command::Identity(IdentityAction::RejectJoin(join.join_id.clone())),cx)));}for node in &self.snapshot.nodes{page=page.child(self.row(node.name.clone(),if node.revoked{"已撤销"}else if self.snapshot.cached||!self.snapshot.online{"当前状态未验证，显示上次记录"}else if node.online{"在线"}else{"离线，状态待确认"}).child(self.button(SharedString::from(format!("settings-{}",node.device_id)),"读取配置",Command::NodeSettings(node.device_id.clone()),cx)));}page=page.child(self.button("provider","配置 Codex",Command::EditSettings(SettingsKind::Provider(vibeface_client::Provider::Codex)),cx)).child(self.button("node-settings-editor","编辑 Node 配置",Command::EditSettings(SettingsKind::Node),cx)).child(self.button("triage","配置 triage 与 webhook",Command::EditSettings(SettingsKind::Triage),cx)).child(self.button("relay","配置 relay",Command::EditSettings(SettingsKind::Relay),cx));for(provider,label)in[(vibeface_client::Provider::Codex,"Codex"),(vibeface_client::Provider::Cursor,"Cursor"),(vibeface_client::Provider::Claude,"Claude"),(vibeface_client::Provider::Pi,"Pi"),(vibeface_client::Provider::Opencode,"OpenCode")]{page=page.child(self.row(label,"读取就绪状态与可用模型后再配置。").child(self.button(SharedString::from(format!("provider-edit-{label}")),"编辑配置",Command::EditSettings(SettingsKind::Provider(provider.clone())),cx)).child(self.button(SharedString::from(format!("provider-models-{label}")),"读取模型",Command::ProviderRead{provider:provider.clone(),probe:false},cx)).child(self.button(SharedString::from(format!("provider-probe-{label}")),"探测可用性",Command::ProviderRead{provider,probe:true},cx)));}for token in &self.snapshot.decision_tokens{page=page.child(self.row(token.label.clone(),format!("创建时间 {}",token.created_ms)).child(self.ask(SharedString::from(format!("revoke-token-{}",token.token_id)),"撤销授权码",Command::DecisionTokenRevoke(token.token_id.clone()),cx)));}page=page.child(self.open_editor("create-decision-token","创建并复制新授权码",Editor::DecisionToken,BTreeMap::new(),cx)).child(self.button("refresh-decision-tokens","读取现有授权码",Command::ReadTriage,cx));page=page.child(self.button("test-webhook","测试 Webhook",Command::TestWebhook,cx));page.into_any_element()}
 pub(crate) fn settings(&self,cx:&mut Context<Self>)->AnyElement{self.page().child(self.profile_picker(cx)).child(self.row("外观","与现有 Vibeface 的中性色与紫色焦点保持一致。")).child(Button::new("theme").label(if self.dark{"切换浅色"}else{"切换深色"}).on_click(cx.listener(|this,_,window,cx|{this.dark=!this.dark;crate::theme::apply(this.dark,window,cx);if let Some(host)=&this.host{let mut preferences=host.preferences.clone();preferences.theme=if this.dark{crate::host::Theme::Dark}else{crate::host::Theme::Light};this.send(Command::Host(HostAction::Preferences(preferences)),cx);}cx.notify();}))).child(self.button("system-theme","跟随系统外观",Command::Host(HostAction::Preferences(crate::host::Preferences{theme:crate::host::Theme::System,..self.host.as_ref().map(|h|h.preferences.clone()).unwrap_or_default()})),cx)).child(self.button("notifications","切换系统通知",Command::Host(HostAction::Preferences(crate::host::Preferences{notifications:!self.host.as_ref().map(|h|h.preferences.notifications).unwrap_or(true),..self.host.as_ref().map(|h|h.preferences.clone()).unwrap_or_default()})),cx)).child(self.nav("logs","日志与诊断",Route::Logs,cx)).child(self.nav("transfers","实验与文件传输",Route::Transfers,cx)).child(self.nav("join","加入与恢复",Route::Join,cx)).child(self.ask("confirm-writable","核对并恢复写入",Command::ConfirmWritable,cx)).child(self.button("disconnect","断开当前连接",Command::Disconnect,cx)).into_any_element()}
 pub(crate) fn node(&self,cx:&mut Context<Self>)->AnyElement{let mut page=self.page().child(self.button("owner-node-settings","管理所选本机Node配置",Command::EditOwnerSettings(SettingsKind::Node),cx)).child(self.button("owner-node-provider","管理所选本机Codex配置",Command::EditOwnerSettings(SettingsKind::Provider(vibeface_client::Provider::Codex)),cx)).child("选中的 Node、应用启动的 Node 和后台服务分别管理。扫描和选择不会启动 Node。").child(self.button("node-refresh","重新扫描",Command::Host(HostAction::Refresh),cx)).child(self.button("controller-mode","使用纯控制端",Command::Host(HostAction::Controller),cx)).child(self.button("node-start","启动本机 Node",Command::Host(HostAction::Start),cx)).child(self.button("node-stop","停止应用启动的 Node",Command::Host(HostAction::Stop),cx)).child(self.open_editor("connect-local","连接已选择的本机 Node",Editor::ConnectLocal,BTreeMap::new(),cx)).child(self.button("clear-node","忘记选择，保留数据",Command::Host(HostAction::ClearSelection),cx));if let Some(host)=&self.host{for node in &host.discovery.nodes{page=page.child(self.row(node.data_dir.display().to_string(),format!("{:?} · {}",node.status,node.device_id)).child(self.button(SharedString::from(format!("select-{}",node.device_id)),"选择此 Node",Command::Host(HostAction::Select(node.identity())),cx)).child(self.button(SharedString::from(format!("start-candidate-{}",node.device_id)),"启动此 Node",Command::Host(HostAction::StartCandidate(node.clone())),cx)));}}for(provider,label)in[(vibeface_client::Provider::Codex,"Codex"),(vibeface_client::Provider::Cursor,"Cursor"),(vibeface_client::Provider::Claude,"Claude"),(vibeface_client::Provider::Pi,"Pi"),(vibeface_client::Provider::Opencode,"OpenCode")]{page=page.child(self.button(SharedString::from(format!("owner-provider-{label}")),format!("管理本机{label}配置"),Command::EditOwnerSettings(SettingsKind::Provider(provider)),cx));}page=page.child(self.button("owner-triage","管理本机triage与Webhook",Command::EditOwnerSettings(SettingsKind::Triage),cx)).child(self.button("owner-relay","管理本机relay",Command::EditOwnerSettings(SettingsKind::Relay),cx));for(label,action)in[("安装后台服务",crate::host::BackgroundAction::Install),("启动后台服务",crate::host::BackgroundAction::Start),("停止后台服务",crate::host::BackgroundAction::Stop),("更新后台服务",crate::host::BackgroundAction::Update),("移除后台服务",crate::host::BackgroundAction::Uninstall)]{page=page.child(self.button(label,label,Command::Host(HostAction::Background(action)),cx));}page.into_any_element()}
 pub(crate) fn transfers(&self,cx:&mut Context<Self>)->AnyElement{let d=&self.snapshot.delivery;let mut page=self.page().child(format!("钱包状态 {} · {}",d.wallet.state,d.wallet.reason.clone().unwrap_or_default())).child("付费结果未知时先查询原订单，不能另建订单付款。").child(self.button("transfer-toggle",if d.enabled{"关闭文件传输"}else{"启用免费文件传输"},Command::DeliveryConfigure{enabled:!d.enabled,charity:true,paid:d.paid_enabled},cx)).child(self.button("paid-toggle",if d.paid_enabled{"关闭付费实验"}else{"启用付费实验"},Command::DeliveryConfigure{enabled:d.enabled,charity:d.charity_enabled,paid:!d.paid_enabled},cx)).child(self.open_editor("transfer-prepare","准备文件传输",Editor::Transfer,BTreeMap::from([("mode","charity".into()),("acceptance","recoverable".into()),("max_service_amount","0".into()),("max_gas_amount","0".into())]),cx)).child(self.button("transfer-refresh","刷新传输记录",Command::Transfers,cx));
 for provider in &d.providers{page=page.child(self.row(format!("传输服务设备 {}",provider.device_id),format!("{} · 每窗口价格 {}",if provider.paid{"支持付费"}else{"免费服务"},provider.offer.as_ref().map(|offer|offer.price.as_str()).unwrap_or("未报价"))));}
 for order in &d.orders{let mut row=self.row(order.name.clone().unwrap_or_else(||"加密文件".into()),format!("{} · {} · {} 字节",order.mode,order.phase,order.bytes)).child(format!("接收设备 {} · 传输设备 {}",order.receiver_peer,order.provider_peer)).child(format!("服务费 {} · 网络费上限 {} · 付款状态 {}",order.payment.total,order.payment.gas_cap,order.payment.state)).child(format!("传输费 {} · 暂存预留费 {} · 时效优先费 {}",order.payment.delivery_fee,order.payment.reservation_fee,order.payment.priority_fee)).child(format!("付款钱包 {} · 固定收款钱包 {} · 链 {} · 资产 {}",order.payment.payer.as_deref().unwrap_or("免费"),order.payment.provider_wallet.as_deref().unwrap_or("免费"),order.payment.chain_id.as_deref().unwrap_or("无"),order.payment.asset.as_deref().unwrap_or("无")));if let Some(deadlines)=&order.deadlines{row=row.child(format!("报价截止 {} · 持有截止 {} · 发布密钥截止 {} · 解密截止 {} · 保留至 {} · 时效截止 {}",deadlines.quote_expires_at,deadlines.hold_deadline,deadlines.key_deadline,deadlines.open_deadline,deadlines.retain_until,deadlines.priority_deadline));}for window in &order.windows{row=row.child(format!("窗口 {} · {} · 密文已落盘 {} / {} 字节 · 解密证明 {}",window.index+1,window.state,window.committed_bytes,window.bytes+68,window.decryption_proven));}if order.role=="sender"&&order.phase=="prepared"{row=row.child(self.ask(SharedString::from(format!("confirm-{}",order.order_id)),if order.mode=="paid"{"确认条款并付款"}else{"确认免费发送"},Command::DeliveryConfirm(order.clone()),cx));}if order.role=="receiver"{row=row.child(self.button(SharedString::from(format!("accept-{}",order.order_id)),"接收文件",Command::DeliveryAccept(order.order_id.clone()),cx));}let save_order=order.clone();row=row.child(self.button(SharedString::from(format!("check-{}",order.order_id)),"查询原订单进度",Command::DeliveryReconcile(order.order_id.clone()),cx)).child(Button::new(SharedString::from(format!("save-{}",order.order_id))).label("保存文件").disabled(!can_read_transfer(order)).on_click(cx.listener(move|this,_,_,cx|this.save_transfer(save_order.clone(),cx))));if let Some(error)=&order.error{row=row.child(error.clone());}page=page.child(row);}page.into_any_element()}
 pub(crate) fn unknown_settings_review(&self,cx:&mut Context<Self>)->AnyElement{let Some(view)=&self.snapshot.settings_review else{return div().into_any_element()};let review=&view.review;let mut page=div().flex().flex_col().gap_3().child(self.row("核对原设置操作",format!("操作 {} · Node {}。服务器结果仍未知；关闭不会记为成功。",review.operation_id,review.target_node)));for(name,value)in &view.original_rows{page=page.child(self.row(format!("原意图 · {name}"),value.clone()));}if let Some(error)=&view.read_error{page=page.child(format!("当前配置尚未读取：{error}。只有你已在原设备手动核对，才能说明依据后关闭。"));}else{for(name,value)in &view.current_rows{page=page.child(self.row(format!("当前状态 · {name}"),value.clone()));}}if review.has_secret_changes{page=page.child("本次包含密钥修改。读回不会提供这些值，不能把其他字段一致当作密钥已应用。");}page=page.child(format!("关闭还会取消 {} 项尚未发送的依赖或同序列后续操作。",review.dependent_ids.len())).child(self.button("reconcile-reviewed-settings","查询原回执或可验证状态",Command::Reconcile(review.operation_id.clone()),cx)).child(self.open_editor("close-reviewed-settings","说明核对依据，关闭未知提醒",Editor::CloseSettings(review.clone()),BTreeMap::new(),cx));page.into_any_element()}

 pub(crate) fn save_transfer(&mut self,order:TransferOrder,cx:&mut Context<Self>){let generation=self.snapshot.generation;let network=self.snapshot.network.clone();let directory=std::env::temp_dir();let picker=crate::host::platform::choose_save_path(cx,&directory,order.name.as_deref().unwrap_or("vibeface-file"));cx.spawn(async move|this,cx|{match picker.await{Ok(Some(path))=>{let _=this.update(cx,|this,cx|{if this.same_view_scope(generation,&network){this.send(Command::DeliverySave{order,path},cx);}});},Ok(None)=>{},Err(error)=>{let _=this.update(cx,|this,cx|{this.notice=Some(format!("保存对话框失败：{error}"));cx.notify();});}}}).detach();}
 pub(crate) fn save_diagnostics(&mut self,cx:&mut Context<Self>){let generation=self.snapshot.generation;let network=self.snapshot.network.clone();let picker=crate::host::platform::choose_save_path(cx,&std::env::temp_dir(),"vibeface-diagnostics.json");cx.spawn(async move|this,cx|{if let Ok(Some(path))=picker.await{let _=this.update(cx,|this,cx|{if this.same_view_scope(generation,&network){this.send(Command::DiagnosticsSave(path),cx);}});}}).detach();}
}
